// Écoutes B2 : flashs d'actualité en anglais, rédigés à partir des fiches ACT (act/news.ts), dans le même ordre.
// Seuls les faits et déclarations des fiches sont repris ; les interprétations n'y figurent pas comme des faits.
import type { LanguageExerciseDef } from "../helpers";

type Opt = [text: string, justification: string];

function news(n: number, title: string, text: string, question: string, correct: "a" | "b" | "c", opts: [Opt, Opt, Opt]): LanguageExerciseDef {
  return {
    exerciseId: `EN-NEWS-${String(n).padStart(3, "0")}`,
    subjectCode: "EN",
    kind: "listening",
    title,
    level: "B2",
    text,
    transcriptByDefault: false,
    question,
    options: opts.map(([t, j], i) => {
      const id = ["a", "b", "c"][i];
      return { id, text: t, correct: id === correct, justification: j };
    }),
  };
}

