// Bulletins longs (260 à 330 mots), même ordre et mêmes faits que les fiches ACT.
export type NewsReport = { exerciseId: string; slug: string; category: string; headline: string; report: string; vocabulary: { term: string; fr: string }[] };

function rep(n: number, slug: string, category: string, headline: string, report: string, vocabulary: [string, string][]): NewsReport {
  return {
    exerciseId: `EN-NEWS-${String(n).padStart(3, "0")}`,
    slug,
    category,
    headline,
    report,
    vocabulary: vocabulary.map(([term, fr]) => ({ term, fr })),
  };
}

